export interface Email {
  id: string;
  senderName: string;
  senderEmail: string;
  subject: string;
  body: string;
  timestamp: Date;
  isRead: boolean;
  folder: 'inbox' | 'sent' | 'archive' | 'spam';
  tags: string[];
  avatarColor: string;
}

export interface AIAnalysisResult {
  summary: string;
  sentiment: 'positive' | 'neutral' | 'negative';
  category: 'work' | 'personal' | 'marketing' | 'urgent';
  suggestedActions: string[];
}

export interface ComposeState {
  isOpen: boolean;
  to: string;
  subject: string;
  body: string;
  isGenerating: boolean;
}

export enum ViewMode {
  List = 'LIST',
  Detail = 'DETAIL'
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { AIAnalysisResult } from "../types";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

// Helper to create the schema for analysis
const analysisSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    summary: {
      type: Type.STRING,
      description: "A concise summary of the email content in Turkish.",
    },
    sentiment: {
      type: Type.STRING,
      enum: ["positive", "neutral", "negative"],
      description: "The overall sentiment of the email.",
    },
    category: {
      type: Type.STRING,
      enum: ["work", "personal", "marketing", "urgent"],
      description: "The category the email belongs to.",
    },
    suggestedActions: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "A list of 1-3 short suggested actions the user should take (e.g., 'Reply', 'Archive', 'Schedule meeting').",
    },
  },
  required: ["summary", "sentiment", "category", "suggestedActions"],
};

export const analyzeEmailContent = async (emailBody: string): Promise<AIAnalysisResult | null> => {
  try {
    const model = "gemini-3-flash-preview";
    const prompt = `Aşağıdaki e-posta içeriğini analiz et. Türkçe yanıt ver. JSON formatında çıktı ver.\n\nE-posta İçeriği:\n${emailBody}`;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: analysisSchema,
        systemInstruction: "Sen profesyonel bir e-posta asistanısın. Türkçe konuşuyorsun.",
      },
    });

    const text = response.text;
    if (!text) return null;
    return JSON.parse(text) as AIAnalysisResult;
  } catch (error) {
    console.error("Gemini analiz hatası:", error);
    return null;
  }
};

export const generateReplyDraft = async (
  originalEmailBody: string, 
  tone: 'formal' | 'casual' | 'brief',
  instructions: string
): Promise<string> => {
  try {
    const model = "gemini-3-flash-preview";

    let toneInstruction = "";
    switch (tone) {
      case 'formal': toneInstruction = "Resmi, profesyonel ve saygılı bir dil kullan."; break;
      case 'casual': toneInstruction = "Samimi, arkadaş canlısı ve günlük bir dil kullan."; break;
      case 'brief': toneInstruction = "Çok kısa, öz ve net ol. Gereksiz kelimelerden kaçın."; break;
    }

    const prompt = `
      Aşağıdaki e-postaya bir yanıt taslağı oluştur.

      Orijinal E-posta: "${originalEmailBody}"

      Kullanıcı Talimatları: "${instructions}"

      Ton: ${toneInstruction}

      Sadece yanıt metnini yaz, başlık veya imza bloğu ekleme. Türkçe yaz.
    `;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
    });

    return response.text || "Yanıt oluşturulamadı.";
  } catch (error) {
    console.error("Gemini yanıt oluşturma hatası:", error);
    return "Bir hata oluştuğu için yanıt taslağı oluşturulamadı.";
  }
};

