import React, { useState } from 'react';
import { format } from 'date-fns';
import { tr } from 'date-fns/locale';
import { 
  ArrowLeft, Reply, Trash2, MoreVertical, 
  Sparkles, BrainCircuit, CheckCircle2, AlertCircle, Briefcase, User 
} from 'lucide-react';
import { Email, AIAnalysisResult } from '../types';
import { analyzeEmailContent, generateReplyDraft } from '../services/geminiService';

interface EmailDetailProps {
  email: Email | null;
  onBack: () => void;
  onDelete: (id: string) => void;
}

const EmailDetail: React.FC<EmailDetailProps> = ({ email, onBack, onDelete }) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResult | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [generatedReply, setGeneratedReply] = useState<string>('');
  const [isGeneratingReply, setIsGeneratingReply] = useState(false);
  const [replyTone, setReplyTone] = useState<'formal' | 'casual' | 'brief'>('formal');
  const [showReplyPanel, setShowReplyPanel] = useState(false);

  // Reset state when email changes
  React.useEffect(() => {
    setAnalysis(null);
    setGeneratedReply('');
    setShowReplyPanel(false);
  }, [email]);

  if (!email) {
    return (
      <div className="flex-1 flex items-center justify-center bg-slate-50 text-slate-400">
        <div className="text-center">
          <div className="bg-white p-6 rounded-full inline-block mb-4 shadow-sm">
            <BrainCircuit size={48} className="text-blue-200" />
          </div>
          <p className="text-lg font-medium text-slate-600">Görüntülemek için bir e-posta seçin</p>
          <p className="text-sm">Yapay zeka asistanınız analiz için hazır.</p>
        </div>
      </div>
    );
  }

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const result = await analyzeEmailContent(email.body);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const handleGenerateReply = async () => {
    setIsGeneratingReply(true);
    const draft = await generateReplyDraft(email.body, replyTone, "Onayla ve nazik ol.");
    setGeneratedReply(draft);
    setIsGeneratingReply(false);
  };

  return (
    <div className="flex-1 flex flex-col bg-white h-full overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="md:hidden p-2 hover:bg-slate-100 rounded-full">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>

          <div className="flex gap-2">
            <button 
              onClick={() => onDelete(email.id)}
              className="p-2 hover:bg-slate-100 rounded-lg text-slate-500 hover:text-red-600 transition-colors" 
              title="Sil"
            >
              <Trash2 size={18} />
            </button>
            <button className="p-2 hover:bg-slate-100 rounded-lg text-slate-500" title="Diğer">
              <MoreVertical size={18} />
            </button>
          </div>
        </div>

        <div className="flex gap-3">
          {!analysis && (
            <button 
              onClick={handleAnalyze}
              disabled={isAnalyzing}
              className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-indigo-500 to-purple-600 text-white rounded-lg text-sm font-medium hover:shadow-lg transition-all disabled:opacity-70"
            >
              {isAnalyzing ? (
                 <div className="animate-spin h-4 w-4 border-2 border-white border-t-transparent rounded-full"/>
              ) : (
                <Sparkles size={16} />
              )}
              AI Analiz
            </button>
          )}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 md:p-10">

        {/* Subject & Meta */}
        <div className="mb-8">
           <div className="flex items-start justify-between mb-4">
             <h1 className="text-2xl font-bold text-slate-900 leading-tight">{email.subject}</h1>
             <span className="text-xs text-slate-400 whitespace-nowrap mt-1 bg-slate-50 px-2 py-1 rounded">
               {format(email.timestamp, 'd MMMM yyyy, HH:mm', { locale: tr })}
             </span>
           </div>

           <div className="flex items-center gap-3">
             <div className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold text-white shadow-sm ${email.avatarColor}`}>
                {email.senderName.charAt(0)}
             </div>
             <div>
               <p className="text-sm font-semibold text-slate-900">{email.senderName}</p>
               <p className="text-xs text-slate-500">&lt;{email.senderEmail}&gt;</p>
             </div>
           </div>
        </div>

        {/* AI Analysis Panel */}
        {analysis && (
          <div className="mb-8 bg-gradient-to-br from-indigo-50 via-purple-50 to-white border border-indigo-100 rounded-2xl p-6 shadow-sm animate-in fade-in slide-in-from-top-4">
             <div className="flex items-center gap-2 mb-4 text-indigo-700 font-semibold">
               <Sparkles size={18} />
               <h2>Yapay Zeka Özeti</h2>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-4">
               <div>
                 <p className="text-sm text-slate-700 leading-relaxed mb-4 font-medium">
                   {analysis.summary}
                 </p>
                 <div className="flex gap-2 flex-wrap">
                   <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium border
                     ${analysis.sentiment === 'positive' ? 'bg-green-50 text-green-700 border-green-200' : 
                       analysis.sentiment === 'negative' ? 'bg-red-50 text-red-700 border-red-200' : 
                       'bg-gray-50 text-gray-700 border-gray-200'}`}>
                      {analysis.sentiment === 'positive' ? <CheckCircle2 size={12} /> : analysis.sentiment === 'negative' ? <AlertCircle size={12} /> : null}
                      {analysis.sentiment.toUpperCase()}
                   </span>
                   <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium bg-blue-50 text-blue-700 border border-blue-200">
                     {analysis.category === 'work' ? <Briefcase size={12} /> : <User size={12} />}
                     {analysis.category.toUpperCase()}
                   </span>
                 </div>
               </div>

               <div className="bg-white/60 rounded-xl p-4 border border-indigo-100">
                 <h3 className="text-xs font-bold text-indigo-900 uppercase tracking-wider mb-2">Önerilen Aksiyonlar</h3>
                 <ul className="space-y-2">
                   {analysis.suggestedActions.map((action, idx) => (
                     <li key={idx} className="text-xs text-slate-600 flex items-center gap-2">
                       <div className="w-1.5 h-1.5 rounded-full bg-indigo-400"></div>
                       {action}
                     </li>
                   ))}
                 </ul>
               </div>
             </div>
          </div>
        )}

        {/* Email Body */}
        <div className="prose prose-slate max-w-none text-slate-800 mb-12">
          <p className="whitespace-pre-wrap leading-relaxed">{email.body}</p>
        </div>

        {/* Reply Section */}
        <div className="border-t border-slate-100 pt-6">
          {!showReplyPanel ? (
            <button 
              onClick={() => setShowReplyPanel(true)}
              className="flex items-center gap-2 px-6 py-3 border border-slate-300 rounded-full text-slate-600 hover:bg-slate-50 hover:border-slate-400 transition-all font-medium"
            >
              <Reply size={18} />
              Yanıtla
            </button>
          ) : (
            <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
               <div className="bg-slate-50 px-4 py-3 border-b border-slate-200 flex items-center justify-between">
                 <span className="text-sm font-medium text-slate-700">Yanıt Oluştur</span>
                 <div className="flex items-center gap-2">
                    <span className="text-xs text-slate-500">AI Tonu:</span>
                    <select 
                      value={replyTone}
                      onChange={(e) => setReplyTone(e.target.value as any)}
                      className="text-xs border-none bg-white rounded-md py-1 pl-2 pr-6 focus:ring-0 cursor-pointer shadow-sm"
                    >
                      <option value="formal">Resmi</option>
                      <option value="casual">Samimi</option>
                      <option value="brief">Kısa</option>
                    </select>
                    <button 
                      onClick={handleGenerateReply}
                      disabled={isGeneratingReply}
                      className="ml-2 text-xs bg-indigo-100 text-indigo-700 px-3 py-1 rounded-md hover:bg-indigo-200 transition-colors flex items-center gap-1"
                    >
                      <Sparkles size={12} />
                      {isGeneratingReply ? 'Yazılıyor...' : 'Taslak Oluştur'}
                    </button>
                 </div>
               </div>
               <div className="p-4">
                 <textarea 
                    value={generatedReply}
                    onChange={(e) => setGeneratedReply(e.target.value)}
                    placeholder="Yanıtınızı buraya yazın veya AI ile oluşturun..."
                    className="w-full h-32 resize-none border-none focus:ring-0 text-sm text-slate-700 p-0"
                 ></textarea>
               </div>
               <div className="bg-slate-50 px-4 py-3 border-t border-slate-100 flex justify-end gap-2">
                  <button 
                    onClick={() => { setShowReplyPanel(false); setGeneratedReply(''); }}
                    className="px-4 py-2 text-sm text-slate-600 hover:text-slate-800 font-medium"
                  >
                    Vazgeç
                  </button>
                  <button className="px-6 py-2 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700 shadow-sm transition-colors flex items-center gap-2">
                    <SendIcon size={16} />
                    Gönder
                  </button>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// Helper component
