        {/* Email Detail - Hidden on mobile if viewing list */}
        <div className={`
          ${mobileView === ViewMode.List ? 'hidden md:flex' : 'flex'} 
          flex-1 h-full
        `}>
          <EmailDetail 
            email={selectedEmail}
            onBack={() => setMobileView(ViewMode.List)}
            onDelete={handleDelete}
          />
        </div>

      </div>
    </div>
  );
};

