import React from 'react';
import { Search, ChevronRight } from 'lucide-react';
import { Email } from '../types';

interface ContactListProps {
  emails: Email[];
  selectedSenderEmail: string | null;
  onSelectSender: (email: string) => void;
  searchTerm: string;
  onSearchChange: (term: string) => void;
}

const ContactList: React.FC<ContactListProps> = ({ 
  emails, 
  selectedSenderEmail, 
  onSelectSender,
  searchTerm,
  onSearchChange
}) => {
  // Group emails by sender
  const contacts = React.useMemo(() => {
    const senderMap = new Map();

    emails.forEach(email => {
      if (!senderMap.has(email.senderEmail)) {
        senderMap.set(email.senderEmail, {
          name: email.senderName,
          email: email.senderEmail,
          avatarColor: email.avatarColor,
          count: 0,
          lastEmailDate: email.timestamp,
          hasUnread: false
        });
      }

      const contact = senderMap.get(email.senderEmail);
      contact.count += 1;
      if (email.timestamp > contact.lastEmailDate) {
        contact.lastEmailDate = email.timestamp;
      }
      if (!email.isRead) {
        contact.hasUnread = true;
      }
    });

    return Array.from(senderMap.values()).filter(contact => 
      contact.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      contact.email.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [emails, searchTerm]);

  return (
    <div className="flex flex-col h-full bg-white border-r border-slate-200 w-full md:w-[380px] lg:w-[420px] flex-shrink-0">
      <div className="p-4 border-b border-slate-100 h-16 flex items-center justify-between">
         <h2 className="font-semibold text-slate-800">Kişiler</h2>
         <span className="text-xs bg-slate-100 text-slate-500 px-2 py-1 rounded-full">{contacts.length} Kişi</span>
      </div>

      <div className="p-4 pt-2 border-b border-slate-50">
        <div className="relative w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
          <input
            type="text"
            placeholder="Kişi ara..."
            value={searchTerm}
            onChange={(e) => onSearchChange(e.target.value)}
            className="w-full pl-9 pr-4 py-2 bg-slate-100 border-none rounded-lg text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none transition-shadow"
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto">
        {contacts.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-48 text-slate-400 p-6 text-center">
            <p>Kişi bulunamadı.</p>
          </div>
        ) : (
          <div className="divide-y divide-slate-50">
            {contacts.map((contact) => {
              const isSelected = selectedSenderEmail === contact.email;
              return (
                <div
                  key={contact.email}
                  onClick={() => onSelectSender(contact.email)}
                  className={`group relative p-4 cursor-pointer hover:bg-slate-50 transition-colors flex items-center justify-between
                    ${isSelected ? 'bg-blue-50 hover:bg-blue-50' : 'bg-white'}
                  `}
                >
                  <div className="flex items-center gap-3 overflow-hidden">
                     <div className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold text-white shrink-0 ${contact.avatarColor}`}>
                        {contact.name.charAt(0)}
                     </div>
                     <div className="overflow-hidden">
                       <h3 className={`text-sm truncate font-semibold text-slate-900`}>
                         {contact.name}
                       </h3>
                       <p className="text-xs text-slate-500 truncate">{contact.email}</p>
                     </div>
                  </div>

                  <div className="flex items-center gap-2">
                     {contact.hasUnread && (
                        <span className="w-2.5 h-2.5 bg-blue-600 rounded-full"></span>
                     )}
                     <div className="bg-slate-100 text-slate-600 text-xs font-medium px-2 py-0.5 rounded-full">
                        {contact.count}
                     </div>
                     <ChevronRight size={16} className="text-slate-300" />
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default ContactList;

