import React, { useState, useMemo } from 'react';
import { Menu } from 'lucide-react';
import Sidebar from './components/Sidebar';
import EmailList from './components/EmailList';
import EmailDetail from './components/EmailDetail';
import LoginScreen from './components/LoginScreen';
import ContactList from './components/ContactList';
import PersonDetail from './components/PersonDetail';
import { Email, ViewMode } from './types';
import { MOCK_EMAILS } from './constants';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<string | null>(null);
  const [emails, setEmails] = useState<Email[]>(MOCK_EMAILS);
  const [activeFolder, setActiveFolder] = useState<string>('inbox');
  const [selectedEmailId, setSelectedEmailId] = useState<string | null>(null);
  const [selectedSenderEmail, setSelectedSenderEmail] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // Mobile responsiveness state
  const [mobileView, setMobileView] = useState<ViewMode>(ViewMode.List);

  // LOGIN SCREEN
  if (!currentUser) {
    return <LoginScreen onLogin={(email) => setCurrentUser(email)} />;
  }

  // LOGIC: Filter emails or Contacts based on view
  const filteredEmails = useMemo(() => {
    let list = emails;

    // If not in contacts view, filter by folder
    if (activeFolder !== 'contacts') {
        list = list.filter(e => e.folder === activeFolder);
    }

    // Apply search
    return list.filter(email => {
      const matchesSearch = 
        email.subject.toLowerCase().includes(searchTerm.toLowerCase()) ||
        email.senderName.toLowerCase().includes(searchTerm.toLowerCase()) ||
        email.body.toLowerCase().includes(searchTerm.toLowerCase());
      return matchesSearch;
    });
  }, [emails, activeFolder, searchTerm]);

  // If in Contacts mode, we filter emails for the PersonDetail view
  const personEmails = useMemo(() => {
      if (!selectedSenderEmail) return [];
      return emails.filter(e => e.senderEmail === selectedSenderEmail);
  }, [emails, selectedSenderEmail]);

  const selectedEmail = useMemo(() => 
    emails.find(e => e.id === selectedEmailId) || null
  , [emails, selectedEmailId]);

  const handleSelectEmail = (email: Email) => {
    setSelectedEmailId(email.id);
    setMobileView(ViewMode.Detail);

    // Mark as read
    if (!email.isRead) {
      setEmails(prev => prev.map(e => 
        e.id === email.id ? { ...e, isRead: true } : e
      ));
    }
  };

  const handleSelectSender = (senderEmail: string) => {
      setSelectedSenderEmail(senderEmail);
      setMobileView(ViewMode.Detail);
  };

  const handleCompose = () => {
    alert("Bu demo versiyonunda yeni e-posta penceresi aktif değildir. E-posta yanıtlamayı deneyin!");
  };

  const handleDelete = (id: string) => {
    if (activeFolder === 'trash') {
        setEmails(prev => prev.filter(e => e.id !== id));
    } else {
        setEmails(prev => prev.map(e => 
            e.id === id ? { ...e, folder: 'trash' } : e
        ));
    }

    if (selectedEmailId === id) {
        setSelectedEmailId(null);
        // If coming from PersonDetail, keep detail view open but clear selection? 
        // For simplicity, go back to list
        if (activeFolder !== 'contacts') {
           setMobileView(ViewMode.List);
        }
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveFolder('inbox');
    setSelectedEmailId(null);
    setSelectedSenderEmail(null);
  };

  return (
    <div className="flex h-screen bg-white overflow-hidden">
      {/* Mobile Menu Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/20 z-10 md:hidden"
          onClick={() => setIsSidebarOpen(false)}
        ></div>
      )}

      {/* Sidebar */}
      <Sidebar 
        activeFolder={activeFolder}
        onFolderChange={(folder) => {
            setActiveFolder(folder);
            setSelectedEmailId(null);
            setSelectedSenderEmail(null);
            setMobileView(ViewMode.List);
            if (window.innerWidth < 768) setIsSidebarOpen(false);
        }}
        onCompose={handleCompose}
        isOpen={isSidebarOpen}
        currentUser={currentUser}
        onLogout={handleLogout}
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col md:flex-row h-full overflow-hidden relative">

        {/* Mobile Header (Only visible on mobile) */}
        <div className="md:hidden h-14 bg-white border-b border-slate-200 flex items-center px-4 flex-shrink-0 z-10">
           <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 -ml-2 text-slate-600">
             <Menu size={24} />
           </button>
           <span className="font-semibold text-slate-800 ml-2">
             {activeFolder === 'inbox' ? 'Gelen Kutusu' : 
              activeFolder === 'contacts' ? 'Kişiler' :
              activeFolder === 'sent' ? 'Gönderilenler' : 
              activeFolder === 'archive' ? 'Arşiv' : 'Spam'}
           </span>
        </div>

        {/* MIDDLE COLUMN: Email List OR Contact List */}
        <div className={`
          ${mobileView === ViewMode.Detail ? 'hidden md:flex' : 'flex'} 
          flex-col h-full w-full md:w-auto
        `}>
          {activeFolder === 'contacts' ? (
              <ContactList 
                emails={emails} // Pass all emails to calculate contacts
                selectedSenderEmail={selectedSenderEmail}
                onSelectSender={handleSelectSender}
                searchTerm={searchTerm}
                onSearchChange={setSearchTerm}
              />
          ) : (
              <EmailList 
                emails={filteredEmails}
                selectedEmailId={selectedEmailId}
                onSelectEmail={handleSelectEmail}
                searchTerm={searchTerm}
                onSearchChange={setSearchTerm}
              />
          )}
        </div>

        {/* RIGHT COLUMN: Email Detail OR Person Detail */}
        <div className={`
          ${mobileView === ViewMode.List ? 'hidden md:flex' : 'flex'} 
          flex-1 h-full
        `}>
          {activeFolder === 'contacts' && !selectedEmailId ? (
              <PersonDetail 
                 senderEmail={selectedSenderEmail}
                 emails={personEmails}
                 onBack={() => setMobileView(ViewMode.List)}
                 onSelectEmail={(email) => {
                     // When clicking an email in Person Detail, we want to view that email
                     // We can temporarily switch out of 'contacts' logic visually, or handle it here.
                     // Simplest: Show EmailDetail but provide a back button that goes to PersonDetail?
                     // For this demo: Switch selection
                     handleSelectEmail(email);
                 }}
              />
          ) : (
              <EmailDetail 
                email={selectedEmail}
                onBack={() => {
                    // If we were viewing a specific email inside contacts mode, go back to person detail
                    if (activeFolder === 'contacts' && selectedSenderEmail) {
                        setSelectedEmailId(null);
                        // Stay in detail view mode because PersonDetail takes the whole right pane
                        setMobileView(ViewMode.Detail); 
                    } else {
                        setMobileView(ViewMode.List);
                    }
                }}
                onDelete={handleDelete}
              />
          )}
        </div>

      </div>
    </div>
  );
};

export default App;

