                    <span className="label-text text-[8px] font-black text-orange-600 uppercase tracking-wider mb-0.5">FİRMA</span>
                    <span className="val-text text-[11px] font-black text-slate-950 dark:text-white truncate uppercase w-full text-center">{sample.firmName || '-'}</span>
