import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { SampleData, YarnType, SizeType } from '../types';

interface AssistantProps {
  currentData: SampleData;
  onUpdateData: (newData: SampleData) => void;
}

interface Message {
  role: 'user' | 'model';
  text: string;
  image?: string;
}

export const Assistant: React.FC<AssistantProps> = ({ currentData, onUpdateData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: 'Merhaba! Ben numune asistanınızım. Bana bir teknik föy resmi atabilir veya "Model kodunu X yap" diyerek değişiklik yapabilirsiniz.' }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const [pendingImage, setPendingImage] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isOpen]);

  // Paste Handler (Sadece Asistan açıksan çalışır)
  useEffect(() => {
    if (!isOpen) return;

    const handlePaste = (e: ClipboardEvent) => {
      const items = e.clipboardData?.items;
      if (!items) return;

      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const blob = items[i].getAsFile();
          if (blob) {
            e.preventDefault(); // Ana sayfanın paste eventini engelle
            e.stopPropagation();
            const reader = new FileReader();
            reader.onload = (ev) => setPendingImage(ev.target?.result as string);
            reader.readAsDataURL(blob);
            return; // Sadece ilk resmi al
          }
        }
      }
    };

    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, [isOpen]);

  const handleSend = async () => {
    if ((!input.trim() && !pendingImage) || isLoading) return;

    const userMsg: Message = { role: 'user', text: input, image: pendingImage || undefined };
    setMessages(prev => [...prev, userMsg]);
    setIsLoading(true);
    setInput('');
    setPendingImage(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const systemInstruction = `
        Sen uzman bir Tekstil Numune Asistanısın. Görevin, kullanıcının verdiği metin veya görselden verileri analiz edip JSON formatında çıktı vermek.

        Mevcut Veriler:
        ${JSON.stringify(currentData)}

        Kurallar:
        1. SADECE geçerli bir JSON objesi döndür. Markdown, açıklama veya ek metin EKLEME.
        2. Gelen resim bir teknik föy veya etiket ise: Model Kodu, Müşteri, Tarih, Kumaş/İplik Cinsi, Gramaj gibi bilgileri okumaya çalış.
        3. Kullanıcı "Model kodunu X yap" derse sadece o alanı güncelle.
        4. "yarnType" alanı için şu değerlerden en yakın olanı seç: ${Object.values(YarnType).join(', ')}. Eğer bulamazsan "Pamuk" varsay.
        5. "size" alanı için şu değerlerden birini seç: ${Object.values(SizeType).join(', ')}.
        6. Tarih formatı YYYY-MM-DD olmalı.
        7. Sayısal değerleri (weight, productionTime) number olarak döndür.
        8. Eğer resimden bir bilgi okuyamazsan, mevcut veriyi koru.

        Örnek Çıktı Formatı:
        {
          "modelCode": "...",
          "customerName": "...",
          "yarnType": "...",
          "weight": 250,
          "notes": "..."
        }
      `;

      const promptParts: any[] = [];

      if (userMsg.image) {
        // Base64 header'ı temizle
        const base64Data = userMsg.image.split(',')[1];
        promptParts.push({
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Data
          }
        });
        promptParts.push({ text: "Bu resimdeki teknik detayları analiz et ve JSON'ı güncelle." });
      }

      if (userMsg.text) {
        promptParts.push({ text: userMsg.text });
      }

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          role: 'user',
          parts: promptParts
        },
        config: {
          systemInstruction: systemInstruction,
          responseMimeType: "application/json"
        }
      });

      const responseText = response.text;

      if (responseText) {
        try {
          const parsedData = JSON.parse(responseText);
          // Mevcut veri ile birleştir (API eksik alan gönderirse diye güvenli merge)
          const mergedData = { ...currentData, ...parsedData };
          onUpdateData(mergedData);
          setMessages(prev => [...prev, { role: 'model', text: 'Verileri güncelledim! Kontrol edebilirsiniz.' }]);
        } catch (e) {
          console.error("JSON Parse Hatası:", e);
          setMessages(prev => [...prev, { role: 'model', text: 'Verileri işlerken bir sorun oluştu. Lütfen tekrar deneyin.' }]);
        }
      } else {
         setMessages(prev => [...prev, { role: 'model', text: 'Üzgünüm, bir yanıt oluşturamadım.' }]);
      }

    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, { role: 'model', text: 'Bağlantı hatası oluştu.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* FAB Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="fixed bottom-6 right-6 z-[60] bg-indigo-600 hover:bg-indigo-700 text-white rounded-full p-4 shadow-2xl transition-transform hover:scale-110 flex items-center gap-2 print:hidden"
      >
        <span className="material-symbols-outlined text-3xl">smart_toy</span>
        {isOpen && <span className="font-bold pr-2 animate-in fade-in">Asistan</span>}
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-24 right-6 z-[60] w-[350px] md:w-[400px] h-[500px] bg-white dark:bg-card-dark rounded-2xl shadow-2xl border border-slate-200 dark:border-slate-800 flex flex-col overflow-hidden animate-in slide-in-from-bottom-10 fade-in duration-300 print:hidden">
          {/* Header */}
          <div className="bg-indigo-600 p-4 flex justify-between items-center text-white">
            <div className="flex items-center gap-2">
              <span className="material-symbols-outlined">auto_awesome</span>
              <h3 className="font-bold text-sm">AI Numune Asistanı</h3>
            </div>
            <button onClick={() => setIsOpen(false)} className="hover:bg-white/20 rounded-full p-1">
              <span className="material-symbols-outlined text-sm">close</span>
            </button>
          </div>

          {/* Messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50 dark:bg-slate-900/50">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div 
                  className={`max-w-[85%] rounded-2xl p-3 text-sm font-medium ${
                    msg.role === 'user' 
                      ? 'bg-indigo-600 text-white rounded-br-none' 
                      : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-200 border border-slate-200 dark:border-slate-700 rounded-bl-none shadow-sm'
                  }`}
                >
                  {msg.image && (
                    <img src={msg.image} alt="Upload" className="w-full h-auto rounded-lg mb-2 border border-white/20" />
                  )}
                  <p>{msg.text}</p>
                </div>
              </div>
            ))}
            {isLoading && (
               <div className="flex justify-start">
                 <div className="bg-white dark:bg-slate-800 rounded-2xl rounded-bl-none p-3 border border-slate-200 dark:border-slate-700 shadow-sm">
                   <div className="flex gap-1">
                     <div className="size-2 bg-indigo-500 rounded-full animate-bounce"></div>
                     <div className="size-2 bg-indigo-500 rounded-full animate-bounce delay-100"></div>
                     <div className="size-2 bg-indigo-500 rounded-full animate-bounce delay-200"></div>
                   </div>
                 </div>
               </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className="p-3 bg-white dark:bg-card-dark border-t border-slate-200 dark:border-slate-800">
            {pendingImage && (
              <div className="relative mb-2 inline-block">
                <img src={pendingImage} alt="Preview" className="h-16 rounded-lg border border-slate-300 shadow-sm" />
                <button 
                  onClick={() => setPendingImage(null)}
                  className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-0.5 shadow-md"
                >
                  <span className="material-symbols-outlined text-xs">close</span>
                </button>
              </div>
            )}
            <div className="flex gap-2">
              <input
                ref={inputRef}
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Resim yapıştırın veya yazın..."
                className="flex-1 rounded-xl border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-900 text-sm focus:ring-indigo-500 focus:border-indigo-500 dark:text-white"
              />
              <button 
                onClick={handleSend}
                disabled={isLoading || (!input && !pendingImage)}
                className="bg-indigo-600 disabled:bg-slate-400 text-white rounded-xl p-2.5 flex items-center justify-center transition-colors"
              >
                <span className="material-symbols-outlined">send</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { supabase } from './supabaseClient';
import { Header } from './components/Header';
import { ImageSection } from './components/ImageSection';
import { FormSection } from './components/FormSection';
import { PreviewModal } from './components/PreviewModal';
import { LoginPage } from './components/LoginPage';
import { ReportsPage } from './components/ReportsPage';
import { ImageResizeModal } from './components/ImageResizeModal';
import { Notifier, NotificationState } from './components/Notifier';
import { Assistant } from './components/Assistant';
import { SampleData, YarnType, SizeType } from './types';

// --- YARDIMCI FONKSİYONLAR ---

const dataURLtoBlob = (dataurl: string) => {
  try {
    const arr = dataurl.split(',');
    const mimeMatch = arr[0].match(/:(.*?);/);
    if (!mimeMatch) return null;

    const mime = mimeMatch[1];
    const bstr = atob(arr[1]);
    let n = bstr.length;
    const u8arr = new Uint8Array(n);

    while (n--) {
      u8arr[n] = bstr.charCodeAt(n);
    }
    return new Blob([u8arr], { type: mime });
  } catch (e) {
    console.error("Blob dönüştürme hatası:", e);
    return null;
  }
};

// Supabase Storage Upload
const uploadImageAndGetURL = async (
  base64Data: string, 
  userId: string, 
  onProgress: (progress: number) => void
): Promise<string> => {
  try {
    onProgress(10);
    const blob = dataURLtoBlob(base64Data);
    if (!blob) throw new Error("Görüntü verisi dönüştürülemedi.");

    // Dosya adı benzersiz olsun
    const uniqueFilename = `${userId}/${Date.now()}.jpg`;
    onProgress(30);

    const { data, error } = await supabase.storage
      .from('sample-images')
      .upload(uniqueFilename, blob, {
        cacheControl: '3600',
        upsert: false
      });

    if (error) throw error;

    onProgress(80);

    // Get Public URL
    const { data: publicUrlData } = supabase.storage
      .from('sample-images')
      .getPublicUrl(uniqueFilename);

    onProgress(100);
    return publicUrlData.publicUrl;
  } catch (error) {
    console.error("Storage upload error:", error);
    throw error;
  }
};

const getInitialData = (): SampleData => ({
  modelCode: "",
  date: new Date().toISOString().split('T')[0],
  customerName: "",
  firmName: "",
  yarnManufacturer: "",
  criticCount: 2,
  weight: 0,
  productionTime: 0,
  size: SizeType.M,
  yarnType: YarnType.Cotton100,
  notes: "",
  mainImage: "",
  details: [],
  isApproved: false
});

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<any | null>(null);
  const [loadingAuth, setLoadingAuth] = useState(true);
  const [currentView, setCurrentView] = useState<'home' | 'reports'>('home');
  const [formData, setFormData] = useState<SampleData>(getInitialData());
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [saveStatus, setSaveStatus] = useState(""); 
  const [searchTerm, setSearchTerm] = useState("");

  const [isUploadingImage, setIsUploadingImage] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);

  const [resizeSource, setResizeSource] = useState<string | null>(null);
  const mainRef = useRef<HTMLElement>(null);

  const [notification, setNotification] = useState<NotificationState | null>(null);

  const showNotification = (message: string, type: 'success' | 'error' = 'error') => {
    setNotification({ message, type });
  };

  const handleSupabaseError = (error: any) => {
    console.error(`HATA:`, error);
    showNotification(error.message || "Bilinmeyen bir hata oluştu.", 'error');
  };

  useEffect(() => {
    // İlk yüklemede session kontrolü
    supabase.auth.getSession().then(({ data: { session } }) => {
      setCurrentUser(session?.user ?? null);
      setLoadingAuth(false);
    });

    // Auth değişimlerini dinle
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setCurrentUser(session?.user ?? null);
      setLoadingAuth(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleLogout = async () => {
    try { 
      const { error } = await supabase.auth.signOut(); 
      if (error) throw error;
      setCurrentUser(null);
      setCurrentView('home');
    } catch (e) { 
      console.error("Çıkış hatası:", e);
      setCurrentUser(null);
      setCurrentView('home');
    }
  };

  const handleFieldChange = useCallback((field: keyof SampleData, value: string | number) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  }, []);

  const handleImageUpload = useCallback(async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => setResizeSource(e.target?.result as string);
      reader.readAsDataURL(file);
    }
  }, []);

  const handleResizeComplete = async (resizedDataUrl: string, sizeKB: number, dims: { width: number, height: number }) => {
    if (!currentUser) {
      showNotification("Resim yüklemek için giriş yapmış olmalısınız.");
      return;
    }
    try {
      setResizeSource(null);
      setIsUploadingImage(true);

      const downloadURL = await uploadImageAndGetURL(resizedDataUrl, currentUser.id, setUploadProgress);

      const urlWithTimestamp = `${downloadURL}?t=${Date.now()}`;

      setFormData(prev => ({ 
        ...prev, 
        mainImage: urlWithTimestamp,
        mainImageSize: sizeKB,
        mainImageDimensions: dims
      }));
      showNotification("Resim optimize edildi ve başarıyla yüklendi!", 'success');

    } catch (error: any) {
      handleSupabaseError(error);
    } finally {
      setIsUploadingImage(false);
    }
  };

  useEffect(() => {
    if (!currentUser || currentView !== 'home') return;
    const handlePaste = async (event: ClipboardEvent) => {
      // Eğer bir input içinde değilsek ve asistan modalı açık değilse ana resim için yapıştırmayı dinle
      // (Asistan kontrolü Assistant.tsx içinde event.stopPropagation ile yapılıyor, burada basitçe devam)
      const target = event.target as HTMLElement;
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') return;

      const items = event.clipboardData?.items;
      if (!items) return;
      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const blob = items[i].getAsFile();
          if (blob) {
            const reader = new FileReader();
            reader.onload = (e) => setResizeSource(e.target?.result as string);
            reader.readAsDataURL(blob);
            break;
          }
        }
      }
    };
    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, [currentUser, currentView]);

  const handleToggleApproval = useCallback(() => {
    setFormData(prev => {
      const nextApprovedState = !prev.isApproved;
      let updatedNotes = prev.notes;
      const approvalText = "NUMUNE SERİ ÜRETİME GİRMİŞTİR";
      const pendingText = "ONAY BEKLİYOR";

      if (nextApprovedState) {
        updatedNotes = updatedNotes.replace(pendingText, "").trim();
        if (!updatedNotes.includes(approvalText)) {
          updatedNotes = updatedNotes ? `${updatedNotes}\n\n${approvalText}` : approvalText;
        }
      } else {
        updatedNotes = updatedNotes.replace(approvalText, "").trim();
        if (!updatedNotes.includes(pendingText)) {
          updatedNotes = updatedNotes ? `${updatedNotes}\n\n${pendingText}` : pendingText;
        }
      }
      return { ...prev, isApproved: nextApprovedState, notes: updatedNotes.trim() };
    });
  }, []);

  const handleSave = async () => {
    if (!currentUser) return;
    if (!formData.modelCode || formData.modelCode.trim() === "") {
      showNotification("Lütfen bir Model Kodu giriniz.");
      return;
    }

    setIsSaving(true);
    setSaveStatus("Veritabanı güncelleniyor...");

    try {
      const cleanMainImage = formData.mainImage ? formData.mainImage.split('?')[0] : "";

      const dbPayload = {
        user_id: currentUser.id,
        model_code: formData.modelCode,
        date: formData.date,
        customer_name: formData.customerName,
        firm_name: formData.firmName,
        yarn_manufacturer: formData.yarnManufacturer,
        critic_count: formData.criticCount,
        weight: formData.weight,
        production_time: formData.productionTime,
        size: formData.size,
        yarn_type: formData.yarnType,
        notes: formData.notes,
        main_image: cleanMainImage,
        main_image_size: formData.mainImageSize,
        main_image_dimensions: formData.mainImageDimensions,
        is_approved: formData.isApproved,
        details: formData.details,
        updated_at: new Date().toISOString()
      };

      let error;
      if (formData.id) {
        const { error: updateError } = await supabase
          .from('samples')
          .update(dbPayload)
          .eq('id', formData.id);
        error = updateError;
      } else {
        const { error: insertError } = await supabase
          .from('samples')
          .insert(dbPayload);
        error = insertError;
      }

      if (error) throw error;

      setSaveStatus("Tamamlandı!");
      showNotification("Numune başarıyla kaydedildi!", 'success');
      setTimeout(() => {
        setFormData(getInitialData());
        setCurrentView('reports');
        setIsSaving(false);
      }, 500);

    } catch (error: any) {
      handleSupabaseError(error);
      setIsSaving(false);
    }
  };

  const handleEditSample = (sample: SampleData) => {
    setFormData(sample);
    setPreviewUrl(null);
    setCurrentView('home');
  };

  const handleNewSample = () => {
    setFormData(getInitialData());
    setPreviewUrl(null);
    setCurrentView('home');
  };

  const handlePrintPdf = () => { window.print(); };

  const handleSaveJpg = async () => {
    if (!mainRef.current) return;
    setIsGenerating(true);
    const element = mainRef.current;
    element.classList.add('capture-mode');
    try {
      // @ts-ignore
      const canvas = await window.html2canvas(element, { useCORS: true, scale: 2 });
      setPreviewUrl(canvas.toDataURL('image/jpeg', 0.9));
    } catch (err) {
      showNotification('Görsel oluşturulamadı.');
    } finally {
      element.classList.remove('capture-mode');
      setIsGenerating(false);
    }
  };

  if (loadingAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background-light dark:bg-background-dark">
         <div className="size-10 border-4 border-primary/20 border-t-primary rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!currentUser) return <LoginPage />;

  return (
    <>
      <Notifier notification={notification} onClose={() => setNotification(null)} />
      <Header 
        onLogout={handleLogout} 
        userEmail={currentUser.email || ''} 
        currentPage={currentView}
        searchTerm={searchTerm}
        onSearch={setSearchTerm}
        onNavigate={(page) => page === 'home' ? handleNewSample() : setCurrentView(page)}
      />

      {currentView === 'home' ? (
        <main ref={mainRef} className="flex-1 w-full max-w-[1440px] mx-auto p-4 md:p-6 lg:p-10 flex flex-col gap-6 print:p-0 animate-in fade-in duration-500">
          <div className="flex flex-col gap-4 print:hidden">
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
              <div className="flex flex-col gap-1">
                <h1 className="text-text-primary-light dark:text-text-primary-dark text-3xl font-extrabold tracking-tight">
                  {formData.id ? 'Numuneyi Düzenle' : 'Yeni Numune Kaydı'}
                </h1>
                <p className="text-text-secondary-light dark:text-text-secondary-dark text-base">Optimize edilmiş resim yönetimi aktif.</p>
              </div>
              <div className="flex flex-wrap gap-2">
                <button onClick={handleSaveJpg} disabled={isGenerating} className="flex items-center gap-2 h-11 px-5 rounded-xl bg-emerald-600 text-white text-sm font-bold shadow-lg hover:bg-emerald-700 disabled:opacity-50 transition-all">
                   <span className="material-symbols-outlined">{isGenerating ? 'hourglass_empty' : 'image'}</span>
                   <span>Görsel Al</span>
                </button>
                <button onClick={handlePrintPdf} className="flex items-center gap-2 h-11 px-5 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-card-dark text-text-primary-light dark:text-text-primary-dark text-sm font-semibold hover:bg-slate-50">
                  <span className="material-symbols-outlined text-[20px]">print</span>
                  <span>Yazdır</span>
                </button>
                <button 
                  onClick={handleSave} 
                  disabled={isSaving}
                  className="flex items-center justify-center gap-2 h-11 px-8 rounded-xl bg-primary text-white text-sm font-bold shadow-lg hover:bg-blue-600 disabled:opacity-70"
                >
                  {isSaving ? (
                    <div className="size-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  ) : (
                    <>
                      <span className="material-symbols-outlined text-[20px]">{formData.id ? 'sync' : 'cloud_upload'}</span>
                      <span>{formData.id ? 'Güncelle' : 'Kaydet'}</span>
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start print:flex print:flex-row-reverse grid-container">
            <div className="lg:col-start-2 lg:col-span-5 print:w-1/2">
              <ImageSection 
                mainImage={formData.mainImage} 
                isApproved={formData.isApproved}
                modelCode={formData.modelCode}
                imageSize={formData.mainImageSize}
                imageDimensions={formData.mainImageDimensions}
                onImageUpload={handleImageUpload} 
                onToggleApproval={handleToggleApproval}
                isUploading={isUploadingImage}
                uploadProgress={uploadProgress}
              />
            </div>
            <div className="lg:col-span-4 print:w-1/2">
              <FormSection data={formData} onChange={handleFieldChange} />
            </div>
          </div>
        </main>
      ) : (
        <main className="flex-1 w-full max-w-[1440px] mx-auto p-4 md:p-6 lg:p-10">
          <ReportsPage userId={currentUser.id} onEdit={handleEditSample} searchTerm={searchTerm} />
        </main>
      )}

      {/* ASİSTAN MODÜLÜ */}
      {currentView === 'home' && currentUser && (
        <Assistant 
          currentData={formData} 
          onUpdateData={(newData) => {
            setFormData(newData);
            showNotification("Numune verileri asistan tarafından güncellendi!", 'success');
          }} 
        />
      )}

      {/* MODALLAR */}
      {resizeSource && (
        <ImageResizeModal 
          image={resizeSource} 
          onResizeComplete={handleResizeComplete} 
          onClose={() => setResizeSource(null)} 
          title="Fotoğrafı Düzenle" 
        />
      )}

      {isSaving && (
        <div className="fixed inset-0 z-[200] bg-white/40 dark:bg-black/40 backdrop-blur-sm flex flex-col items-center justify-center animate-in fade-in duration-300">
           <div className="bg-white dark:bg-card-dark p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4 w-full max-w-sm mx-4 border border-slate-200 dark:border-slate-800">
              <div className="size-16 relative">
                <div className="absolute inset-0 border-4 border-primary/20 rounded-full"></div>
                <div className="absolute inset-0 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
              </div>
              <div className="text-center">
                <p className="text-lg font-bold text-text-primary-light dark:text-text-primary-dark">Buluta Aktarılıyor</p>
                <p className="text-sm text-primary font-semibold animate-pulse">{saveStatus}</p>
              </div>
           </div>
        </div>
      )}

      {previewUrl && (
        <PreviewModal 
          imageUrl={previewUrl} 
          modelCode={formData.modelCode}
          customerName={formData.customerName}
          onClose={() => setPreviewUrl(null)} 
          onDownload={() => {
            const safeModel = (formData.modelCode || 'model').replace(/[^a-z0-9]/gi, '_');
            const safeCustomer = (formData.customerName || 'musteri').replace(/[^a-z0-9]/gi, '_');
            const link = document.createElement('a');
            link.href = previewUrl;
            link.download = `${safeModel}_${safeCustomer}.jpg`;
            link.click();
            setPreviewUrl(null);
          }}
        />
      )}

      {isGenerating && (
        <div className="fixed inset-0 z-[110] bg-white/60 dark:bg-black/60 backdrop-blur-md flex flex-col items-center justify-center">
          <div className="size-12 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin mb-4"></div>
          <p className="text-lg font-bold">Görsel Kartı Hazırlanıyor</p>
        </div>
      )}
    </>
  );
};

