import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../supabaseClient';
import { SampleData } from '../types';

interface ReportsPageProps {
  userId: string;
  onEdit: (data: SampleData) => void;
  searchTerm?: string;
}

export const ReportsPage: React.FC<ReportsPageProps> = ({ userId, onEdit, searchTerm = "" }) => {
  const [samples, setSamples] = useState<SampleData[]>([]);
  const [loading, setLoading] = useState(true);
  const [isCapturing, setIsCapturing] = useState<string | null>(null);

  const formatDate = (dateStr: string) => {
    if (!dateStr) return "-";
    const parts = dateStr.split('-');
    if (parts.length !== 3) return dateStr;
    return `${parts[2]}.${parts[1]}.${parts[0]}`;
  };

  const fetchSamples = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from('samples')
        .select('*')
        .eq('user_id', userId)
        .order('updated_at', { ascending: false });
      if (error) throw error;
      setSamples((data || []).map((item: any) => ({
        id: item.id,
        modelCode: item.model_code,
        date: item.date,
        customerName: item.customer_name,
        firmName: item.firm_name,
        yarnManufacturer: item.yarn_manufacturer,
        criticCount: item.critic_count,
        weight: item.weight,
        productionTime: item.production_time,
        size: item.size,
        yarnType: item.yarn_type,
        notes: item.notes,
        mainImage: item.main_image,
        isApproved: item.is_approved,
        updatedAt: item.updated_at
      })));
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  useEffect(() => { if (userId) fetchSamples(); }, [userId]);

  const filteredSamples = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return samples.filter(s => s.modelCode.toLowerCase().includes(term) || s.customerName.toLowerCase().includes(term));
  }, [samples, searchTerm]);

  const handleDownloadCard = async (sampleId: string, modelCode: string, customerName: string) => {
    const cardElement = document.getElementById(`sample-card-${sampleId}`);
    if (!cardElement) return;
    setIsCapturing(sampleId);
    try {
      // @ts-ignore
      const canvas = await window.html2canvas(cardElement, {
        useCORS: true,
        scale: 4, 
        width: 250, 
        windowWidth: 250,
        backgroundColor: "#ffffff",
        logging: false,
        onclone: (clonedDoc) => {
          const card = clonedDoc.getElementById(`sample-card-${sampleId}`);
          if (card) {
            card.style.width = '250px';
            card.style.height = 'auto'; 
            card.style.minHeight = 'auto';
            card.style.borderRadius = '0';
            card.style.border = 'none';
            card.style.padding = '0';
            card.style.display = 'flex';
            card.style.flexDirection = 'column';
            card.style.boxShadow = 'none';

            // Fotoğraf Üzerindeki Etiket Renkleri (Capture Mode)
            const badges = card.querySelectorAll('.img-badge');
            badges.forEach(b => {
               const text = (b as HTMLElement).innerText;
               if(text.includes('MODEL')) (b as HTMLElement).style.backgroundColor = '#eef2ff'; // Indigo-50
               else (b as HTMLElement).style.backgroundColor = '#ecfeff'; // Cyan-50
               (b as HTMLElement).style.borderColor = '#cbd5e1';
            });

            const imgArea = card.querySelector('.img-area');
            if (imgArea) {
              // TAM BOY GÖRSEL AYARLARI
              (imgArea as HTMLElement).style.height = 'auto'; // Sabit yükseklik kaldırıldı
              (imgArea as HTMLElement).style.minHeight = '200px'; // Minimum denge
              (imgArea as HTMLElement).style.flex = 'none'; // Flex kısıtlaması kaldırıldı
              (imgArea as HTMLElement).style.borderBottom = '1px solid #e2e8f0';
              (imgArea as HTMLElement).style.display = 'block';

              const img = imgArea.querySelector('img');
              if(img) {
                  img.style.padding = '0';
                  img.style.width = '100%';
                  img.style.height = 'auto'; // Resim kendi yüksekliğini alsın
                  img.style.objectFit = 'contain'; // Kesilme olmasın
                  img.style.position = 'relative'; // Absolute position iptal
              }
            }

            const contentArea = card.querySelector('.content-area');
            if (contentArea) {
              (contentArea as HTMLElement).style.padding = '10px';
              (contentArea as HTMLElement).style.gap = '5px';
              const grids = contentArea.querySelectorAll('.grid');
              const allItems: HTMLElement[] = [];
              grids.forEach(g => {
                g.querySelectorAll(':scope > div').forEach(i => allItems.push(i as HTMLElement));
                g.remove();
              });

              const newGrid = clonedDoc.createElement('div');
              newGrid.style.display = 'grid';
              newGrid.style.gridTemplateColumns = 'repeat(2, 1fr)';
              newGrid.style.gap = '4px';

              const colorMap: Record<string, { bg: string, border: string }> = {
                'TARİH': { bg: '#f1f5f9', border: '#e2e8f0' },
                'FİRMA': { bg: '#ffedd5', border: '#fed7aa' },
                'BEDEN': { bg: '#ede9fe', border: '#ddd6fe' },
                'GRAMAJ': { bg: '#ffe4e6', border: '#fecdd3' },
                'SÜRE': { bg: '#e0f2fe', border: '#bae6fd' },
                'KRİTİK': { bg: '#fef3c7', border: '#fde68a' }, // Amber-100 (Sarı)
                'İPLİK CİNSİ': { bg: '#d1fae5', border: '#a7f3d0' }
              };

              allItems.forEach(item => {
                const labelEl = item.querySelector('span.label-text');
                const labelText = labelEl ? (labelEl as HTMLElement).innerText.trim() : '';
                const style = colorMap[labelText] || { bg: '#f8fafc', border: '#cbd5e1' };

                item.style.padding = '4px 2px';
                item.style.height = '42px'; // Biraz büyütüldü
                item.style.border = `1px solid ${style.border}`;
                item.style.backgroundColor = style.bg;
                item.style.display = 'flex';
                item.style.flexDirection = 'column';
                item.style.alignItems = 'center';
                item.style.justifyContent = 'center';
                item.style.borderRadius = '8px';

                const labels = item.querySelectorAll('span.label-text');
                labels.forEach(l => { 
                    (l as HTMLElement).style.fontSize = '9px'; // 7'den 9'a
                    (l as HTMLElement).style.fontWeight = '900';
                    (l as HTMLElement).style.color = '#475569';
                });

                const vals = item.querySelectorAll('span.val-text');
                vals.forEach(v => { 
                    (v as HTMLElement).style.fontSize = '13px'; // 10'dan 13'e
                    (v as HTMLElement).style.fontWeight = '900'; 
                    (v as HTMLElement).style.color = '#000000';
                    (v as HTMLElement).style.lineHeight = '1.5'; // Capture mode fix
                    (v as HTMLElement).style.paddingBottom = '2px';
                });

                if (labelText.includes('İPLİK')) {
                   item.style.gridColumn = '1 / -1';
                   item.style.height = 'auto';
                   item.style.minHeight = '42px';
                }
                newGrid.appendChild(item);
              });
              contentArea.insertBefore(newGrid, contentArea.firstChild);
            }

            const notes = card.querySelector('.notes-area');
            if (notes) {
              (notes as HTMLElement).style.marginTop = '4px';
              (notes as HTMLElement).style.backgroundColor = '#fffbeb'; 
              (notes as HTMLElement).style.padding = '10px';
              (notes as HTMLElement).style.border = '1px solid #fde68a';
              (notes as HTMLElement).style.borderRadius = '12px';
              const p = notes.querySelector('p');
              if (p) { 
                p.style.fontSize = '11px'; 
                p.style.fontWeight = '900'; 
                p.style.lineHeight = '1.4'; 
                p.style.color = '#000000';
              }
            }
          }
        }
      });
      const link = document.createElement('a');
      const safeModel = (modelCode || 'model').replace(/[^a-z0-9]/gi, '_');
      link.download = `${safeModel}_Kart.jpg`;
      link.href = canvas.toDataURL('image/jpeg', 1.0);
      link.click();
    } catch (err) { console.error(err); } finally { setIsCapturing(null); }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("Bu numune kaydını silmek istediğinize emin misiniz?")) return;
    await supabase.from('samples').delete().eq('id', id);
    setSamples(prev => prev.filter(s => s.id !== id));
  };

  if (loading) return <div className="py-20 text-center font-black animate-pulse text-indigo-600 tracking-widest">ARŞİV YÜKLENİYOR...</div>;

  return (
    <div className="space-y-8 pb-20">
      <div className="flex justify-between items-center border-b pb-6">
        <h2 className="text-3xl font-black text-slate-800 dark:text-white">NUMUNE ARŞİVİ <span className="text-indigo-500">({filteredSamples.length})</span></h2>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-x-6 gap-y-10">
        {filteredSamples.map((sample) => (
          <div key={sample.id} className="flex flex-col gap-3 group">

            <div 
              id={`sample-card-${sample.id}`} 
              className="bg-white dark:bg-card-dark rounded-[24px] overflow-hidden shadow-sm border border-slate-200 dark:border-slate-800 flex flex-col relative transition-transform duration-300 hover:shadow-lg hover:-translate-y-1"
            >
              {isCapturing === sample.id && (
                <div className="absolute inset-0 z-50 bg-white/95 flex items-center justify-center font-black text-[10px] text-indigo-600 animate-pulse uppercase tracking-widest">
                  Hazırlanıyor...
                </div>
              )}

              <div className="img-area relative h-[280px] bg-slate-50 dark:bg-slate-900 flex items-center justify-center border-b border-slate-100 dark:border-slate-800/50 overflow-hidden">
                {sample.mainImage ? (
                  <img src={sample.mainImage} className="w-full h-full object-cover" alt="sample" />
                ) : (
                  <span className="material-symbols-outlined text-4xl text-slate-300">image_not_supported</span>
                )}

                <div className="absolute bottom-3 left-3 flex flex-col gap-1.5 items-start z-10 w-full pr-28">
                  <div className="img-badge bg-indigo-100/95 dark:bg-indigo-900/30 backdrop-blur-sm px-3 py-1.5 rounded-xl border border-indigo-200 dark:border-indigo-800/50 shadow-md flex flex-col min-w-[90px]">
                    <span className="text-[7px] font-black text-indigo-600 dark:text-indigo-400 block uppercase tracking-wider mb-0.5">MODEL</span>
                    <p className="text-slate-900 dark:text-white font-black text-[13px] uppercase leading-normal truncate w-full pb-1">{sample.modelCode}</p>
                  </div>
                  <div className="img-badge bg-cyan-100/95 dark:bg-cyan-900/30 backdrop-blur-sm px-3 py-1.5 rounded-xl border border-cyan-200 dark:border-cyan-800/50 shadow-md flex flex-col min-w-[90px]">
                    <span className="text-[7px] font-black text-cyan-600 dark:text-cyan-400 block uppercase tracking-wider mb-0.5">MÜŞTERİ</span>
                    <p className="text-slate-900 dark:text-white font-black text-[11px] uppercase truncate max-w-[120px] leading-normal pb-1">{sample.customerName || '-'}</p>
                  </div>
                </div>

                <div className="absolute bottom-3 right-3 z-20">
                  <div className={`${sample.isApproved ? 'bg-emerald-50' : 'bg-amber-50'} dark:bg-slate-900/90 border-2 ${sample.isApproved ? 'border-emerald-500' : 'border-orange-400'} border-double rounded-2xl p-2.5 shadow-xl transform -rotate-6 min-w-[80px]`}>
                    <div className={`px-2 py-0.5 rounded-full ${sample.isApproved ? 'bg-emerald-500' : 'bg-orange-400'} text-slate-950 text-[8px] font-black uppercase tracking-widest text-center mb-1`}>
                      {sample.isApproved ? 'ONAYLI' : 'BEKLEMEDE'}
                    </div>
                     <div className="flex flex-col items-center justify-center gap-0.5">
                        {sample.isApproved && (
                          <span className="material-symbols-outlined text-[16px] text-emerald-600">
                            verified
                          </span>
                        )}
                        <span className={`text-[7px] font-black uppercase ${sample.isApproved ? 'text-emerald-950' : 'text-orange-950'} text-center leading-snug whitespace-pre-line pb-0.5`}>
                           {sample.isApproved ? 'İMALAT İÇİN\nUYGUNDUR' : 'ONAY\nBEKLENİYOR'}
                        </span>
                     </div>
                  </div>
                </div>
              </div>

              <div className="content-area p-4 flex-1 flex flex-col gap-2">
                {/* 1. Satır: Tarih & Firma */}
                <div className="grid grid-cols-2 gap-2">
                  <div className="bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-2 rounded-xl flex flex-col items-center justify-center">
                    <span className="label-text text-[8px] font-black text-slate-600 uppercase tracking-wider mb-0.5">TARİH</span>
                    <span className="val-text text-[11px] font-black text-slate-950 dark:text-white leading-normal pb-1">{formatDate(sample.date)}</span>
                  </div>
                  <div className="bg-orange-100 dark:bg-orange-900/30 border border-orange-200 dark:border-orange-800/50 p-2 rounded-xl flex flex-col items-center justify-center overflow-hidden">
                    <span className="label-text text-[8px] font-black text-orange-600 uppercase tracking-wider mb-0.5">FİRMA</span>
                    <span className="val-text text-[11px] font-black text-slate-950 dark:text-white truncate uppercase w-full text-center leading-normal pb-1">{sample.firmName || '-'}</span>
                  </div>
                </div>

                {/* 2. Satır: Beden & Gramaj */}
                <div className="grid grid-cols-2 gap-2">
                  <div className="bg-violet-100 dark:bg-violet-900/30 border border-violet-200 dark:border-violet-800/50 p-2 rounded-xl text-center flex flex-col justify-center min-h-[50px]">
                    <span className="label-text text-[8px] font-black text-violet-600 uppercase tracking-wider mb-0.5">BEDEN</span>
                    <span className="val-text text-[14px] font-black text-slate-950 dark:text-white leading-normal pb-1">{sample.size}</span>
                  </div>
                  <div className="bg-rose-100 dark:bg-rose-900/30 border border-rose-200 dark:border-rose-800/50 p-2 rounded-xl text-center flex flex-col justify-center min-h-[50px]">
                    <span className="label-text text-[8px] font-black text-rose-600 uppercase tracking-wider mb-0.5">GRAMAJ</span>
                    <span className="val-text text-[14px] font-black text-slate-950 dark:text-white leading-normal pb-1">{sample.weight}g</span>
                  </div>
                </div>

                {/* 3. Satır: Süre & Kritik */}
                <div className="grid grid-cols-2 gap-2">
                  <div className="bg-sky-100 dark:bg-sky-900/30 border border-sky-200 dark:border-sky-800/50 p-1.5 rounded-xl text-center flex flex-col justify-center min-h-[45px]">
                    <span className="label-text text-[8px] font-black text-sky-600 uppercase tracking-wider mb-0.5">SÜRE</span>
                    <span className="val-text text-[12px] font-black text-slate-950 dark:text-white leading-normal pb-1">{sample.productionTime} dk</span>
                  </div>
                  <div className="bg-amber-100 dark:bg-amber-900/30 border border-amber-200 dark:border-amber-800/50 p-1.5 rounded-xl text-center flex flex-col justify-center min-h-[45px]">
                    <span className="label-text text-[8px] font-black text-amber-600 uppercase tracking-wider mb-0.5">KRİTİK</span>
                    <span className="val-text text-[12px] font-black text-slate-950 dark:text-white leading-normal pb-1">{sample.criticCount}</span>
                  </div>
                </div>

                {/* 4. Satır: İplik Cinsi */}
                <div className="grid grid-cols-1">
                   <div className="bg-emerald-100 dark:bg-emerald-900/30 border border-emerald-200 dark:border-emerald-800/50 p-2 rounded-xl text-center flex flex-col justify-center min-h-[45px]">
                      <span className="label-text text-[8px] font-black text-emerald-600 uppercase tracking-wider mb-0.5">İPLİK CİNSİ</span>
                      <span className="val-text text-[11px] font-black text-slate-950 dark:text-white truncate px-2 leading-normal pb-1">{sample.yarnType}</span>
                   </div>
                </div>

                {sample.notes && (
                  <div className="notes-area bg-amber-50 dark:bg-amber-900/20 p-3 rounded-xl border border-amber-200 dark:border-amber-800/50 relative mt-1 shadow-inner">
                    <p className="text-[11px] font-black text-slate-950 dark:text-white leading-[1.4] uppercase line-clamp-3">
                      {sample.notes}
                    </p>
                  </div>
                )}
              </div>
            </div>

            <div className="bg-white dark:bg-card-dark rounded-xl p-2 shadow-sm border border-slate-200 dark:border-slate-800 flex items-center gap-2 h-14">
                <button 
                  onClick={() => onEdit(sample)} 
                  className="flex-1 h-full bg-slate-50 dark:bg-slate-800 text-indigo-600 dark:text-indigo-400 font-bold rounded-lg text-[10px] uppercase hover:bg-indigo-50 dark:hover:bg-slate-700 border border-slate-100 dark:border-slate-700 flex flex-col items-center justify-center gap-0.5 transition-colors"
                >
                  <span className="material-symbols-outlined text-[18px]">edit_square</span>
                  <span>Düzenle</span>
                </button>
                <div className="w-px h-8 bg-slate-200 dark:bg-slate-700"></div>
                <button 
                  onClick={() => handleDownloadCard(sample.id!, sample.modelCode, sample.customerName)} 
                  className="flex-1 h-full bg-slate-50 dark:bg-slate-800 text-emerald-600 dark:text-emerald-400 font-bold rounded-lg text-[10px] uppercase hover:bg-emerald-50 dark:hover:bg-slate-700 border border-slate-100 dark:border-slate-700 flex flex-col items-center justify-center gap-0.5 transition-colors"
                >
                  <span className="material-symbols-outlined text-[18px]">download</span>
                  <span>İndir</span>
                </button>
                <div className="w-px h-8 bg-slate-200 dark:bg-slate-700"></div>
                <button 
                  onClick={() => handleDelete(sample.id!)} 
                  className="flex-1 h-full bg-slate-50 dark:bg-slate-800 text-rose-500 font-bold rounded-lg text-[10px] uppercase hover:bg-rose-50 dark:hover:bg-slate-700 border border-slate-100 dark:border-slate-700 flex flex-col items-center justify-center gap-0.5 transition-colors"
                >
                  <span className="material-symbols-outlined text-[18px]">delete</span>
                  <span>Sil</span>
                </button>
            </div>

          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../supabaseClient';
import { SampleData } from '../types';
import { PreviewModal } from './PreviewModal';

interface ReportsPageProps {
  userId: string;
  onEdit: (data: SampleData) => void;
  searchTerm?: string;
}

export const ReportsPage: React.FC<ReportsPageProps> = ({ userId, onEdit, searchTerm = "" }) => {
  const [samples, setSamples] = useState<SampleData[]>([]);
  const [loading, setLoading] = useState(true);
  const [isCapturing, setIsCapturing] = useState<string | null>(null);

  // Preview Modal State
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [previewData, setPreviewData] = useState<{model: string, customer: string} | null>(null);

  const formatDate = (dateStr: string) => {
    if (!dateStr) return "-";
    const parts = dateStr.split('-');
    if (parts.length !== 3) return dateStr;
    return `${parts[2]}.${parts[1]}.${parts[0]}`;
  };

  const fetchSamples = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from('samples')
        .select('*')
        .eq('user_id', userId)
        .order('updated_at', { ascending: false });
      if (error) throw error;
      setSamples((data || []).map((item: any) => ({
        id: item.id,
        modelCode: item.model_code,
        date: item.date,
        customerName: item.customer_name,
        firmName: item.firm_name,
        yarnManufacturer: item.yarn_manufacturer,
        criticCount: item.critic_count,
        weight: item.weight,
        productionTime: item.production_time,
        size: item.size,
        yarnType: item.yarn_type,
        notes: item.notes,
        mainImage: item.main_image,
        isApproved: item.is_approved,
        updatedAt: item.updated_at
      })));
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  useEffect(() => { if (userId) fetchSamples(); }, [userId]);

  const filteredSamples = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return samples.filter(s => s.modelCode.toLowerCase().includes(term) || s.customerName.toLowerCase().includes(term));
  }, [samples, searchTerm]);

  const handleGeneratePreview = async (sampleId: string, modelCode: string, customerName: string) => {
    const cardElement = document.getElementById(`sample-card-${sampleId}`);
    if (!cardElement) return;
    setIsCapturing(sampleId);

    try {
      // @ts-ignore
      const canvas = await window.html2canvas(cardElement, {
        useCORS: true,
        scale: 4, // Yüksek kalite
        width: 250, 
        windowWidth: 250,
        backgroundColor: "#ffffff",
        logging: false,
        onclone: (clonedDoc) => {
          const card = clonedDoc.getElementById(`sample-card-${sampleId}`);
          if (card) {
            // Ana Kart Stilleri
            card.style.width = '250px';
            card.style.height = 'auto'; 
            card.style.minHeight = 'auto';
            card.style.borderRadius = '0';
            card.style.border = 'none';
            card.style.padding = '0';
            card.style.display = 'flex';
            card.style.flexDirection = 'column';
            card.style.boxShadow = 'none';
            card.style.fontFamily = 'Arial, sans-serif'; // Garantili font

            // --- GÖRSEL ALANI DÜZELTMELERİ ---
            const badges = card.querySelectorAll('.img-badge');
            badges.forEach(b => {
               const el = b as HTMLElement;
               const text = el.innerText;

               // Renkleri netleştir
               if(text.includes('MODEL')) el.style.backgroundColor = '#eef2ff'; 
               else el.style.backgroundColor = '#ecfeff';
               el.style.borderColor = '#cbd5e1';

               // Rozet içindeki metinlerin kesilmesini önle
               const pTags = el.querySelectorAll('p');
               pTags.forEach(p => {
                 p.style.lineHeight = '1.4';
                 p.style.paddingBottom = '4px'; // Harf kuyrukları için ekstra boşluk
                 p.style.marginBottom = '0';
                 p.style.overflow = 'visible';
                 p.style.whiteSpace = 'normal'; // Satır sarmaya izin ver gerekirse
               });
            });

            // Mühür Alanı Düzeltmeleri
            const stampTexts = card.querySelectorAll('.stamp-container span');
            stampTexts.forEach(s => {
                (s as HTMLElement).style.lineHeight = '1.4';
                (s as HTMLElement).style.paddingBottom = '5px';
            });

            const imgArea = card.querySelector('.img-area');
            if (imgArea) {
              (imgArea as HTMLElement).style.height = 'auto';
              (imgArea as HTMLElement).style.minHeight = '220px'; // Biraz daha yüksek
              (imgArea as HTMLElement).style.flex = 'none';
              (imgArea as HTMLElement).style.borderBottom = '1px solid #e2e8f0';
              (imgArea as HTMLElement).style.display = 'block';

              const img = imgArea.querySelector('img');
              if(img) {
                  img.style.padding = '0';
                  img.style.width = '100%';
                  img.style.height = 'auto';
                  img.style.objectFit = 'contain';
                  img.style.position = 'relative';
              }
            }

            // --- İÇERİK ALANI DÜZELTMELERİ ---
            const contentArea = card.querySelector('.content-area');
            if (contentArea) {
              (contentArea as HTMLElement).style.padding = '10px';
              (contentArea as HTMLElement).style.gap = '6px';

              // Grid yapısını yeniden oluştur (html2canvas grid gap sorunlarını önlemek için)
              const grids = contentArea.querySelectorAll('.grid');
              const allItems: HTMLElement[] = [];
              grids.forEach(g => {
                g.querySelectorAll(':scope > div').forEach(i => allItems.push(i as HTMLElement));
                g.remove();
              });

              const newGrid = clonedDoc.createElement('div');
              newGrid.style.display = 'grid';
              newGrid.style.gridTemplateColumns = 'repeat(2, 1fr)';
              newGrid.style.gap = '6px'; // Gap artırıldı

              const colorMap: Record<string, { bg: string, border: string }> = {
                'TARİH': { bg: '#f1f5f9', border: '#e2e8f0' },
                'FİRMA': { bg: '#ffedd5', border: '#fed7aa' },
                'BEDEN': { bg: '#ede9fe', border: '#ddd6fe' },
                'GRAMAJ': { bg: '#ffe4e6', border: '#fecdd3' },
                'SÜRE': { bg: '#e0f2fe', border: '#bae6fd' },
                'KRİTİK': { bg: '#fef3c7', border: '#fde68a' },
                'İPLİK CİNSİ': { bg: '#d1fae5', border: '#a7f3d0' }
              };

              allItems.forEach(item => {
                const labelEl = item.querySelector('span.label-text');
                const labelText = labelEl ? (labelEl as HTMLElement).innerText.trim() : '';
                const style = colorMap[labelText] || { bg: '#f8fafc', border: '#cbd5e1' };

                // Kutu Stilleri
                item.style.padding = '6px 4px'; // Padding artırıldı
                item.style.minHeight = '50px'; // Yükseklik artırıldı
                item.style.height = 'auto';
                item.style.border = `1px solid ${style.border}`;
                item.style.backgroundColor = style.bg;
                item.style.display = 'flex';
                item.style.flexDirection = 'column';
                item.style.alignItems = 'center';
                item.style.justifyContent = 'center';
                item.style.borderRadius = '8px';
                item.style.overflow = 'visible'; // Taşan yazıları kesme

                // Label Stilleri
                const labels = item.querySelectorAll('span.label-text');
                labels.forEach(l => { 
                    (l as HTMLElement).style.fontSize = '9px';
                    (l as HTMLElement).style.fontWeight = '900';
                    (l as HTMLElement).style.color = '#475569';
                    (l as HTMLElement).style.marginBottom = '2px';
                    (l as HTMLElement).style.display = 'block';
                });

                // Değer Stilleri (Kesilmeyi önleyen kritik ayarlar)
                const vals = item.querySelectorAll('span.val-text');
                vals.forEach(v => { 
                    (v as HTMLElement).style.fontSize = '13px';
                    (v as HTMLElement).style.fontWeight = '900'; 
                    (v as HTMLElement).style.color = '#000000';
                    (v as HTMLElement).style.lineHeight = '1.4'; // Satır yüksekliği
                    (v as HTMLElement).style.paddingBottom = '3px'; // Alt boşluk
                    (v as HTMLElement).style.display = 'block';
                    (v as HTMLElement).style.overflow = 'visible';
                });

                if (labelText.includes('İPLİK')) {
                   item.style.gridColumn = '1 / -1';
                }
                newGrid.appendChild(item);
              });
              contentArea.insertBefore(newGrid, contentArea.firstChild);
            }

            const notes = card.querySelector('.notes-area');
            if (notes) {
              (notes as HTMLElement).style.marginTop = '6px';
              (notes as HTMLElement).style.backgroundColor = '#fffbeb'; 
              (notes as HTMLElement).style.padding = '12px';
              (notes as HTMLElement).style.border = '1px solid #fde68a';
              (notes as HTMLElement).style.borderRadius = '12px';
              const p = notes.querySelector('p');
              if (p) { 
                p.style.fontSize = '11px'; 
                p.style.fontWeight = '900'; 
                p.style.lineHeight = '1.5'; 
                p.style.color = '#000000';
                p.style.paddingBottom = '2px';
              }
            }
          }
        }
      });

      const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
      setPreviewUrl(dataUrl);
      setPreviewData({ model: modelCode, customer: customerName });

    } catch (err) { 
      console.error(err); 
      alert("Görsel oluşturulurken bir hata oluştu.");
    } finally { 
      setIsCapturing(null); 
    }
  };

  const handleDownload = () => {
    if (!previewUrl || !previewData) return;
    const link = document.createElement('a');
    const safeModel = (previewData.model || 'model').replace(/[^a-z0-9]/gi, '_');
    link.download = `${safeModel}_Kart.jpg`;
    link.href = previewUrl;
    link.click();
    setPreviewUrl(null); // İndirdikten sonra kapat
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("Bu numune kaydını silmek istediğinize emin misiniz?")) return;
    await supabase.from('samples').delete().eq('id', id);
    setSamples(prev => prev.filter(s => s.id !== id));
  };

  if (loading) return <div className="py-20 text-center font-black animate-pulse text-indigo-600 tracking-widest">ARŞİV YÜKLENİYOR...</div>;

  return (
    <>
      <div className="space-y-8 pb-20">
        <div className="flex justify-between items-center border-b pb-6">
          <h2 className="text-3xl font-black text-slate-800 dark:text-white">NUMUNE ARŞİVİ <span className="text-indigo-500">({filteredSamples.length})</span></h2>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-x-6 gap-y-10">
          {filteredSamples.map((sample) => (
            <div key={sample.id} className="flex flex-col gap-3 group">

              <div 
                id={`sample-card-${sample.id}`} 
                className="bg-white dark:bg-card-dark rounded-[24px] overflow-hidden shadow-sm border border-slate-200 dark:border-slate-800 flex flex-col relative transition-transform duration-300 hover:shadow-lg hover:-translate-y-1"
              >
                {isCapturing === sample.id && (
                  <div className="absolute inset-0 z-50 bg-white/95 flex items-center justify-center font-black text-[10px] text-indigo-600 animate-pulse uppercase tracking-widest">
                    Görsel Hazırlanıyor...
                  </div>
                )}

                <div className="img-area relative h-[280px] bg-slate-50 dark:bg-slate-900 flex items-center justify-center border-b border-slate-100 dark:border-slate-800/50 overflow-hidden">
                  {sample.mainImage ? (
                    <img src={sample.mainImage} className="w-full h-full object-cover" alt="sample" />
                  ) : (
