      {/* Önizleme Modalı */}
      {previewUrl && previewData && (
        <PreviewModal 
          imageUrl={previewUrl}
          modelCode={previewData.model}
          customerName={previewData.customer}
          onClose={() => setPreviewUrl(null)}
          onDownload={handleDownload}
        />
      )}
    </>
  );
};

import React, { useRef, useState, useEffect } from 'react';

